<!--vbase-->
<template>
  <div class="row highlighted-back q-pl-md q-pr-md">
    <div class="secondary-c-text text-h6">
      <q-btn flat rounded data-cy="dashboard" color="primary" to="/dashboard">
        <q-icon class="text-red-13" size="sm">
          <Icon icon="mdi:arrow-left" width="24" height="24" />
        </q-icon>
        <label
          style="
            vertical-align: middle;
            margin-left: 10px;
            font-size: 20px;
            cursor: pointer;
          "
          >{{ $t('dashboard') }}</label
        >
      </q-btn>
    </div>
  </div>

  <div class="row full-width" style="padding-left: 35px">
    <div class="col-9">
      <div class="full-width back-white">
        <iframe
          :src="path"
          title="Main menu"
          width="100%"
          height="900px"
        ></iframe>
      </div>
    </div>

    <div class="col-3">
      <div class="images-list" style="margin-left: 33px; margin-right: 33px">
        <div class="full-width back-white q-ma-sm scroll-area-height">
          <div class="row justify-center q-pl-md q-pr-md q-pt-md">
            <span class="text-red-13 text-h6 text-weight-bold"> Details </span>
          </div>
          <div
            class="q-pl-md q-pr-md q-mt-md full-width left-scroll-area-height scrolle-y"
          >
            <div>
              <span class="text-weight-bold">Classification Class:</span>
              {{ classification.classification_label_class || '' }}
            </div>

            <div>
              <span class="text-weight-bold">Classification Label:</span>
              {{ classification.classification_label }}
            </div>

            <div class="q-mt-md">
              <span class="text-weight-bold"
                >{{ $t('Re-Classifiy Document') }}:</span
              >
            </div>

            <div class="q-mt-md">
              <labelsDropdown />
            </div>

            <div class="q-mt-md">
              <q-btn
                :label="$t('proceed')"
                color="primary"
                @click="restartDoc"
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
  <q-inner-loading :showing="processing">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import cache from 'src/utils/cache';
import { defineComponent, ref } from 'vue';
import { DOC2API_URL } from 'src/pages/APIs';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { documentDetailApiService } from 'src/services';
import labelsDropdown from 'src/components/document/classification/labels_dropdown.vue';
import { useImageAuth } from 'src/composables/useImageAuth';

import {
  useDocumentStore,
  useDocClassificationStore } from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [cache],
  components: {
    labelsDropdown,
    
  },
  mounted() {
    this.init();
  },

  unmounted: function () {
    // unmounted
  },
  data() {
    return {
      docId: '',
      filename: '',
    };
  },
  methods: {
    async init() {
      try {
        await this.getTokenQueryParam();
        this.processing = true;
        this.docId = this.$route.params.id as string;
        this.filename = this.$route.params.filename as string;
        this.path =
          DOC2API_URL +
          '/resource/document/' +
          this.docId +
          '/' +
          this.docId +
          '.pdf?download=false' +
          '&' +
          this.tokenQueryParam;

        if (!this.path) {
          logInfo('pdf not found');
        }

        await this.getInvoiceDataByDocId(this.docId);
        if (
          !this.record ||
          Object.keys(this.record).length === 0 ||
          this.record.success === false
        ) {
          return;
        }
        this.classification = this.record.classification;
      } catch (err: any) {
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    async getInvoiceDataByDocId(docId: string) {
      try {
        this.record = [];
        await this.getDocumentById(docId);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    async restartDoc() {
      try {
        this.processing = true;
        let data = {} as dynamicObj;

        if (this.selected_custom_model_label) {
          data.doc_classification_label = this.selected_custom_model_label;
        }

        await documentDetailApiService.restartClassification(data, this.docId);
        this.resetStore();
        notify.success(this.$t('NEW_CLASSIFICATION'));
        this.$router.push('/dashboard');
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record, doctype, error } = storeToRefs(doc_store);
    const { getDocumentById, setRecordFromCache } = doc_store;

    const classification_store = useDocClassificationStore();
    const { resetStore } = classification_store;
    const { selected_custom_model_label } = storeToRefs(classification_store);

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();

    return {
      resetStore,
      selected_custom_model_label,
      getDocumentById,
      getTokenQueryParam: refreshTokenParam,
      setRecordFromCache,
      path: ref(''),
      processing: ref(false),
      record,
      doctype,
      error,
      classification: ref({} as any),
      tokenQueryParam,
    };
  },
});
</script>

